sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var a = api.data.record.form.fields;
    var b = api.data.decision_side_panel.form.fields;

    // Log objects for debugging
    console.log('Fields from record:', a);
    console.log('Fields from decision side panel before update:', b);

    for (var key in a) {
        if (b.hasOwnProperty(key)) {
            b[key] = a[key];
        }

    }
    api.data.decision_side_panel.form.fields = b;

    console.log('Fields from decision side panel after update:', api.data.decision_side_panel.form.fields);
}
